def parse_stock(lines):
    """Return (stock, skipped): stock maps item -> net quantity."""
    stock = {}
    skipped = 0
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = [p.strip() for p in line.split(",")]
        if len(parts) != 2 or not parts[0] or not parts[1].startswith(("+", "-")):
            skipped += 1
            continue
        try:
            qty = int(parts[1])  # int() accepts a leading + or -
        except ValueError:
            skipped += 1
            continue
        item = parts[0].lower()
        stock[item] = stock.get(item, 0) + qty
    return stock, skipped


def format_report(stock):
    rows = sorted(((name, qty) for name, qty in stock.items() if qty != 0), key=lambda r: (-r[1], r[0]))
    return "\n".join(f"{name}: {qty}" + (" (!)" if qty < 0 else "") for name, qty in rows)
